sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    (function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

        var fileId = source.getValue('u_google_file_id');
        var fileName = source.getValue('u_image');
        if (!fileId) return;
        // Check if image already attached
        var existingAttach = new GlideRecord('sys_attachment');
        existingAttach.addQuery('table_name', String(target.getTableName()));
        existingAttach.addQuery('table_sys_id', String(target.getUniqueValue()));
        existingAttach.addQuery('file_name', fileName);
        existingAttach.query();
        if (existingAttach.hasNext()) {
            log.info('Image "' + fileName + '" already attached — skipping.');
            return;
        }
        // Fetch from Google Drive (public share)
        var url = 'https://drive.google.com/uc?export=download&id=' + fileId;
        var request = new sn_ws.RESTMessageV2();
        request.setEndpoint(url);
        request.setHttpMethod('GET');
        request.setFollowAllRedirects(true);
        request.setRequestHeader('Accept', 'image/*');
        var response = request.execute();
        var status = response.getStatusCode();
        if (status == 200) {
            var sa = new GlideSysAttachment();
            sa.writeBase64(
                target,
                fileName || 'workspace_image.jpg',
                response.getHeader('Content-Type') || 'image/jpeg',
                GlideStringUtil.base64Encode(response.getBody())
            );
            log.info('Attached "' + fileName + '" to ' + target.getValue('name'));
        } else {
            log.warn('Failed to fetch "' + fileName + '" (HTTP ' + status + ')');
        }

    })(source, map, log, target);

})(source, map, log, target);
